# Find border vs interior cells by checking 4-neighbors
def is_border_cell(grid, r, c, color):
    if grid[r][c] == 0:
        return False  # Not border, it's background
    neighbors = []
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            neighbors.append(grid[nr][nc])
    return min(neighbors) == 0  # Border cell is surrounded by background or 0s

def is_interior_cell(grid, r, c, color):
    if grid[r][c] == 0:
        return False
    # Interior cell is surrounded by same color or border cells on all 4 sides
    neighbors = []
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            neighbors.append(grid[nr][nc])
    return all(n != 0 and n == color or is_border_cell(grid, nr, nc, color) for n in neighbors)

